import MenuCard from "./MenuCard";

export default function MenuGrid({ menu = [], cart = [], addToCart, removeFromCart }) {

  const getQty = (id) => {
    const found = cart.find(i => i.id === id);
    return found ? found.quantity : 0;
  };

  if (!Array.isArray(menu) || menu.length === 0) {
    return <p style={{ padding: 20 }}>No menu items available</p>;
  }

  return (
    <div className="menu-grid">
      {menu.map(item => {
        const qty = getQty(item.id);

        // robust detection
        const rating = Number(item.avg_rating || item.rating || 0);
        const sold = Number(item.sold || item.sold_count || item.total_sold || 0);

        const isTopRated = rating >= 4.5;
        const isPopular = sold >= 10;

        return (
          <MenuCard
            key={item.id}
            item={item}
            quantity={qty}
            addToCart={addToCart}
            removeFromCart={removeFromCart}
            isTopRated={isTopRated}
            isPopular={isPopular}
            rating={rating}
            sold={sold}
          />
        );
      })}
    </div>
  );
}
